<?php require __DIR__.'/partials/header.php'; $role=$_GET['ruolo']??'';$search=trim($_GET['q']??'');$sql='SELECT * FROM players WHERE 1';$args=[];if($role!==''){$sql.=' AND position=?';$args[]=$role;}if($search!==''){$sql.=' AND name LIKE ?';$args[]='%'.$search.'%';}$sql.=' ORDER BY jersey_number';$st=$db->prepare($sql);$st->execute($args);$rows=$st->fetchAll(); ?><section class="page-hero"><div class="wrap"><span class="eyebrow">ROSTER · 2026/27</span><h1>LA <em>SQUADRA</em></h1><p>Il gruppo che scende in campo. I profili e le statistiche sono dimostrativi.</p></div></section><section class="wrap section"><form class="filters" method="get"><input name="q" value="<?= e($search) ?>" placeholder="Cerca giocatore..."><select name="ruolo"><option value="">Tutti i ruoli</option><?php foreach(['Playmaker','Guardia','Ala piccola','Ala grande','Centro'] as $r): ?><option <?= $role===$r?'selected':'' ?>><?= e($r) ?></option><?php endforeach; ?></select><button class="btn btn-red">Filtra</button></form><div class="player-grid"><?php foreach($rows as $p): ?><a class="player-card" href="giocatore.php?id=<?= (int)$p['id'] ?>"><div class="player-photo"><img loading="lazy" src="<?= e($p['image_url']?:'assets/images/player.svg') ?>" alt="Avatar demo di <?= e($p['name']) ?>"><b>#<?= (int)$p['jersey_number'] ?></b></div><div class="player-info"><small><?= e($p['position']) ?> · <?= e($p['nationality']) ?></small><h3><?= e($p['name']) ?></h3><span><?= number_format((float)$p['points_avg'],1) ?> punti di media</span></div></a><?php endforeach; ?></div><?php if(!$rows): ?><p class="empty">Nessun giocatore trovato.</p><?php endif; ?></section><?php require __DIR__.'/partials/footer.php'; ?>